#include <vector>

class Solution {
public:
    int minOperations(std::vector<int>& nums, std::vector<int>& locked, int k) {
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            if (locked[i] == 1 && nums[i] != i + 1) return -1;
        }
        std::vector<bool> vis(n, false);
        int swaps = 0;
        for (int i = 0; i < n; ++i) {
            if (!vis[i] && locked[i] == 0 && nums[i] != i + 1) {
                int cycle = 0, curr = i;
                while (!vis[curr] && locked[curr] == 0) {
                    vis[curr] = true;
                    cycle++;
                    curr = nums[curr] - 1;
                }
                if (cycle > 1) swaps += (cycle - 1);
            }
        }
        return swaps;
    }
};

class Solution {
